        }
    }
    if (valid.isEmpty()) {
        return 0;
    }

    // If only one non‑empty string, the answer is its full length
    if (valid.size() == 1) {
        return valid.get(0).length();
    }

    // Determine the minimal string length (upper bound for the answer)
    int minLen = Integer.MAX_VALUE;
    for (String s : valid) {
